mapper.delete:
DELETE FROM search_doc
WHERE target_type = #{targetType}
  AND target_id = #{targetId}

choose.when:
SELECT 1 AS targetType, sd.target_id AS targetId, COALESCE(NULLIF(p.title, ''), LEFT(p.content, 40)) AS title, IF(CHAR_LENGTH(p.content) > 120, CONCAT(LEFT(p.content, 120), '...'), p.content) AS summary, IFNULL(p.like_count, 0) AS likeCount, IFNULL(p.comment_count, 0) AS commentCount, IFNULL(p.view_count, 0) AS viewCount, sd.published_at AS publishedAt FROM search_doc sd JOIN post p ON p.id = sd.target_id AND p.deleted_at IS NULL WHERE sd.target_type = 1 AND sd.status = 1 AND MATCH(sd.search_text) AGAINST(#{keyword} IN BOOLEAN MODE)
AND ( sd.published_at < #{lastPublishedAt} OR (sd.published_at = #{lastPublishedAt} AND sd.target_id < #{lastId}) )
ORDER BY sd.published_at DESC, sd.target_id DESC LIMIT #{limit}

SELECT 2 AS targetType, sd.target_id AS targetId, a.title AS title, IF(CHAR_LENGTH(CONCAT_WS(' ', a.location, a.summary)) > 120, CONCAT(LEFT(CONCAT_WS(' ', a.location, a.summary), 120), '...'), CONCAT_WS(' ', a.location, a.summary)) AS summary, IFNULL(a.like_count, 0) AS likeCount, IFNULL(a.comment_count, 0) AS commentCount, IFNULL(a.view_count, 0) AS viewCount, sd.published_at AS publishedAt FROM search_doc sd JOIN activity a ON a.id = sd.target_id AND a.deleted_at IS NULL WHERE sd.target_type = 2 AND sd.status = 1 AND MATCH(sd.search_text) AGAINST(#{keyword} IN BOOLEAN MODE)
AND ( sd.published_at < #{lastPublishedAt} OR (sd.published_at = #{lastPublishedAt} AND sd.target_id < #{lastId}) )
ORDER BY sd.published_at DESC, sd.target_id DESC LIMIT #{limit}
